SELECT id, service, latency_ms, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, context['trace'] AS trace, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace FROM app_logs WHERE service IN ('auth', 'search')
